import {contactPanel} from './author.js';
import{services,products,projects,money,estimate,cartTotal,getState,save,reset,book,checkout}from './data.js';
import{objectArt,carArtFor}from './art.js';
const routes=['automotive','commerce','studio','control'];let category='Все',sort='default',filter='Все',query='',lastMessage='';
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('#notice').textContent=message;$('#notice').hidden=false}
function modal(title,body){$('#dialog-content').innerHTML=`<h2>${title}</h2>${body}`;$('#dialog').showModal()}
function persist(){if(!save())toast('Изменения работают в памяти, но браузер не разрешил сохранение. Не закрывайте страницу.')}
function head(name,tag,title,desc){const titles={'01 — AUTOMOTIVE':'01 — АВТОСЕРВИС','02 — OBJECTS STORE':'02 — МАГАЗИН','03 — CREATOR STUDIO':'03 — СТУДИЯ','04 — CONTROL CENTER':'04 — УПРАВЛЕНИЕ'};return `<div class="module-nav"><a href="#/">← На главную</a>${routes.map((r,i)=>`<a ${r===name?'aria-current="page"':''} href="#/${r}">${['Автосервис','Магазин','Студия','Управление'][i]}</a>`).join('')}</div><div class="module-heading"><div><p class="eyebrow">${titles[tag]||tag} / ДЕМОНСТРАЦИЯ</p><h1>${title}</h1></div><p>${desc}</p></div><p class="demo-note">Демонстрационный проект · Все действия остаются в этой вкладке. Реальных заявок, покупок и отправки данных нет.</p><div id="notice" role="status" hidden></div>`}
function auto(experience){const s=getState();return head('automotive','01 — AUTOMOTIVE','Точность.<br><em>В каждой детали.</em>','Выберите автомобиль и услуги. Соберите предварительный расчёт и попробуйте демо-запись.')+`<div class="workbench"><section><div class="section-top"><h2>${experience?'Внутри мастерской':'Ваш автомобиль'}</h2><a href="#/automotive${experience?'':'/experience'}">${experience?'Обычный каталог':'Войти в гараж'} ↗</a></div><label class="field">Кузов автомобиля<select id="vehicle">${['Седан','Универсал','Хэтчбек','SUV'].map(v=>`<option ${s.vehicle===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="garage"><div id="car-visual">${carArtFor(s.vehicle)}</div><div class="hotspots">${services.map((v,i)=>`<button data-service="${v.id}" aria-pressed="${s.services.includes(v.id)}" style="--i:${i}"><span>0${i+1}</span>${v.name}</button>`).join('')}</div></div><p class="muted">Выберите зону автомобиля или услугу в списке ниже.</p><div class="service-list">${services.map(v=>`<label class="service"><input type="checkbox" value="${v.id}" ${s.services.includes(v.id)?'checked':''}><span><b>${v.name}</b><small>${v.desc} · ${v.time} мин</small></span><strong>${money(v.price*(s.vehicle==='SUV'?1.2:1))}</strong></label>`).join('')}</div></section><aside class="summary"><p class="eyebrow">ВАШ ПЛАН ОБСЛУЖИВАНИЯ</p><h2>Всё прозрачно.</h2><div id="estimate"></div><form id="booking"><label class="field">Демонстрационное время<select id="slot"><option>Завтра · 10:00</option><option>Завтра · 12:00</option><option>Завтра · 15:00</option><option>Послезавтра · 11:00</option></select></label><button class="primary" type="submit">Создать демо-запись</button></form><p class="muted">Цены иллюстративные. Для SUV коэффициент ×1,2. Итог — сумма выбранных услуг; оплата не требуется.</p><a href="#/control">Посмотреть записи →</a></aside></div>${contactPanel()}`}
function updateEstimate(){const s=getState();$('#estimate').innerHTML=`<p>${s.services.length} услуг · ${services.filter(v=>s.services.includes(v.id)).reduce((n,v)=>n+v.time,0)} мин</p><div class="total">${money(estimate(s.services,s.vehicle))}</div>`;$('#booking button').disabled=!s.services.length;document.querySelectorAll('[data-service]').forEach(el=>el.setAttribute('aria-pressed',s.services.includes(el.dataset.service)));document.querySelectorAll('.service input').forEach(el=>el.checked=s.services.includes(el.value))}
function bindAuto(){updateEstimate();const toggle=id=>{const s=getState();s.services=s.services.includes(id)?s.services.filter(x=>x!==id):[...s.services,id];persist();updateEstimate()};document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>toggle(b.dataset.service));document.querySelectorAll('.service input').forEach(b=>b.onchange=()=>toggle(b.value));$('#vehicle').onchange=e=>{getState().vehicle=e.target.value;persist();$('#car-visual').innerHTML=carArtFor(e.target.value);document.querySelectorAll(".service").forEach((row,i)=>row.querySelector("strong").textContent=money(estimate([services[i].id],e.target.value)));updateEstimate()};$('#booking').onsubmit=e=>{e.preventDefault();try{const b=book($('#slot').value);modal('Демо-запись создана',`<p>${esc(b.vehicle)} · ${esc(b.slot)}</p><p>${money(b.total)} · ${b.services.length} услуг</p><p>Это симуляция. Мастерская не получала заявку.</p><button id="to-control" class="primary">Открыть Control Center</button>`);$('#to-control').onclick=()=>{$('#dialog').close();location.hash='#/control'}}catch(err){toast(err.message)}}}
function commerce(){return head('commerce','02 — OBJECTS STORE','Вещи с характером.<br><em>Пространство для жизни.</em>','Небольшая коллекция предметов. Исследуйте формы, сохраните понравившееся и соберите свою корзину.')+`<div class="shop-tools"><div class="chips">${['Все','Свет','Мебель','Декор'].map(c=>`<button data-cat="${c}" aria-pressed="${category===c}">${c}</button>`).join('')}</div><label class="field">Поиск<input id="search" type="search" placeholder="Название предмета" value="${esc(query)}"></label><label class="field">Порядок<select id="sort"><option value="default">Коллекция</option><option value="low" ${sort==='low'?'selected':''}>Сначала дешевле</option><option value="high" ${sort==='high'?'selected':''}>Сначала дороже</option></select></label></div><div class="workbench shop"><section id="products"></section><aside class="summary"><p class="eyebrow">ВАША ПОДБОРКА</p><h2>Корзина</h2><div id="cart"></div></aside></div>${contactPanel()}`}
function drawProducts(){const s=getState();let list=products.filter(p=>(category==='Все'||category===p.cat)&&p.name.toLocaleLowerCase().includes(query.toLocaleLowerCase()));if(sort!=='default')list.sort((a,b)=>sort==='low'?a.price-b.price:b.price-a.price);$('#products').innerHTML=list.length?`<div class="product-grid">${list.map(p=>`<article class="product"><button class="art-button" data-detail="${p.id}" aria-label="Подробнее: ${p.name}">${objectArt(p.shape,p.color)}</button><div class="product-info"><small>${p.cat}</small><h3>${p.name}</h3><b>${money(p.price)}</b><div><button data-add="${p.id}">В корзину +</button><button data-favorite="${p.id}" aria-label="В избранное: ${p.name}" aria-pressed="${s.favorites.includes(p.id)}">${s.favorites.includes(p.id)?'♥':'♡'}</button></div></div></article>`).join('')}</div>`:'<div class="empty">Ничего не найдено. Попробуйте другую категорию или название.</div>';$('#products').querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>add(b.dataset.add));$('#products').querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{const id=b.dataset.favorite;s.favorites=s.favorites.includes(id)?s.favorites.filter(x=>x!==id):[...s.favorites,id];persist();drawProducts()});$('#products').querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const p=products.find(x=>x.id===b.dataset.detail);modal(p.name,`<div class="detail-art">${objectArt(p.shape,p.color)}</div><p>${p.desc}</p><p>${money(p.price)} · Демонстрационный товар</p><button class="primary" id="detail-add">Добавить в корзину</button>`);$('#detail-add').onclick=()=>{add(p.id);$('#dialog').close()}})}
function add(id){const s=getState();s.cart[id]=Math.min(20,(s.cart[id]||0)+1);persist();drawCart();toast('Предмет добавлен в корзину.')}
function drawCart(){const s=getState(),list=products.filter(p=>s.cart[p.id]);$('#cart').innerHTML=list.length?list.map(p=>`<div class="cart-line"><span>${p.name}<small>${money(p.price*s.cart[p.id])}</small></span><div><button data-qty="${p.id}" data-delta="-1" aria-label="Уменьшить количество ${p.name}">−</button><b>${s.cart[p.id]}</b><button data-qty="${p.id}" data-delta="1" aria-label="Увеличить количество ${p.name}">+</button></div></div>`).join('')+`<div class="total">${money(cartTotal(s.cart))}</div><p class="muted">Доставка и платежи не моделируются.</p><button class="primary" id="checkout">Оформить демо-заказ</button>`:'<div class="empty">Здесь появятся выбранные предметы.</div>';$('#cart').querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{s.cart[b.dataset.qty]=Math.max(0,Math.min(20,s.cart[b.dataset.qty]+Number(b.dataset.delta)));persist();drawCart()});$('#checkout')?.addEventListener('click',()=>{const o=checkout();drawCart();modal('Коллекция собрана',`<p>Демо-заказ на ${money(o.total)} создан. Оплата не списывалась, товары не будут отправлены.</p><button id="order-control" class="primary">Посмотреть заказ</button>`);$('#order-control').onclick=()=>{$('#dialog').close();location.hash='#/control'}})}
function studio(){return head('studio','03 — CREATOR STUDIO','Наблюдать.<br><em>Создавать. Исследовать.</em>','Галерея концептуальных исследований JORGEN TECH PLANET. Откройте проект, чтобы узнать идею и подход.')+`<div class="chips">${['Все','Архитектура','Предметы','Цифровое'].map(c=>`<button data-filter="${c}" aria-pressed="${filter===c}">${c}</button>`).join('')}</div><div class="gallery">${projects.filter(p=>filter==='Все'||filter===p.cat).map((p,i)=>`<button class="gallery-item" data-project="${p.id}"><div class="gallery-art" style="background:${p.color}30">${objectArt(p.id==='objects'?'vase':p.id==='systems'?'lamp':'building',p.color)}</div><small>ИССЛЕДОВАНИЕ / ${p.cat}</small><h2>${p.name} ↗</h2><p>${p.text}</p></button>`).join('')}</div><section class="studio-note"><p class="eyebrow">THE PRACTICE</p><h2>От наблюдения — к работающему продукту.</h2><p>Эти работы созданы как демонстрационные концепты внутри планеты. Здесь нет вымышленных заказчиков и коммерческих результатов.</p><button id="brief">Собрать краткий бриф ↗</button></section>${contactPanel()}`}
function bindStudio(){document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderModule('studio')});document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{const p=projects.find(x=>x.id===b.dataset.project);modal(p.name,`<div class="detail-art">${objectArt(p.id==='objects'?'vase':'building',p.color)}</div><p>${p.text}</p><h3>Подход</h3><p>${p.process}</p><p class="eyebrow">КОНЦЕПТ JORGEN TECH PLANET · НЕ КЛИЕНТСКИЙ КЕЙС</p>`)});$('#brief').onclick=()=>{modal('Сформулируйте идею',`<form id="brief-form"><label class="field">Тип проекта<select id="brief-type"><option>Сайт-портфолио</option><option>Интернет-магазин</option><option>Сервис записи</option></select></label><label class="field">Главная задача<textarea id="brief-goal" required maxlength="500" placeholder="Например: показать коллекцию и помочь выбрать товар"></textarea></label><button class="primary">Подготовить текст</button></form><p class="muted">Локальный помощник. Ничего не отправляет автору.</p><pre id="brief-result"></pre>`);$('#brief-form').onsubmit=e=>{e.preventDefault();$('#brief-result').textContent=`Проект: ${$('#brief-type').value}\nЗадача: ${$('#brief-goal').value}\nНужно уточнить: аудиторию, контент, сроки и бюджет.\n\nСкопируйте этот текст для дальнейшего обсуждения.`}}}
function control(){const s=getState();return head('control','04 — CONTROL CENTER','Всё под контролем.<br><em>В пределах вашей сессии.</em>','Записи из мастерской и заказы магазина появляются здесь сразу. Изменяйте статусы и исследуйте связь между приложениями.')+`<div class="stats"><article><small>ДЕМО-ЗАПИСИ</small><strong>${s.bookings.length}</strong></article><article><small>ДЕМО-ЗАКАЗЫ</small><strong>${s.orders.length}</strong></article><article><small>СУММА ДЕМО-ЗАКАЗОВ</small><strong>${money(s.orders.filter(o=>o.status!=='Отменён').reduce((n,o)=>n+o.total,0))}</strong></article></div><section class="records"><h2>Мастерская</h2>${s.bookings.length?s.bookings.map(b=>`<article class="record"><div><b>${esc(b.vehicle)} · ${esc(b.slot)}</b><p>${b.services.map(id=>services.find(v=>v.id===id)?.name).filter(Boolean).join(', ')}</p><small>${money(b.total)} · ${esc(b.id.slice(0,8))}</small></div><label class="field">Статус<select data-booking="${esc(b.id)}">${['Новая','Подтверждена','Завершена','Отменено'].map(v=>`<option ${b.status===v?'selected':''}>${v}</option>`).join('')}</select></label></article>`).join(''):'<p class="empty">Записей пока нет. <a href="#/automotive">Создать первую →</a></p>'}<h2>Магазин</h2>${s.orders.length?s.orders.map(o=>`<article class="record"><div><b>Заказ ${esc(o.id.slice(0,8))}</b><p>${products.filter(p=>o.items[p.id]).map(p=>p.name+' × '+o.items[p.id]).join(', ')}</p><small>${money(o.total)}</small></div><label class="field">Статус<select data-order="${esc(o.id)}">${['Новый','Собирается','Завершён','Отменён'].map(v=>`<option ${o.status===v?'selected':''}>${v}</option>`).join('')}</select></label></article>`).join(''):'<p class="empty">Заказов пока нет. <a href="#/commerce">Открыть коллекцию →</a></p>'}</section><section class="session-tools"><div><h2>Чистый лист</h2><p>Сброс удаляет демозаписи, заказы, корзину и избранное только в этой вкладке.</p></div><button id="reset-demo">Сбросить демосессию</button></section>${contactPanel()}`}
function bindControl(){for(const [attr,key]of[['booking','bookings'],['order','orders']])document.querySelectorAll(`[data-${attr}]`).forEach(el=>el.onchange=()=>{getState()[key].find(x=>x.id===el.dataset[attr]).status=el.value;persist();toast('Статус обновлён.');if(key==='orders')renderModule('control')});$('#reset-demo').onclick=()=>{modal('Начать заново?',`<p>Будут удалены все записи и заказы этой демосессии. Состояние острова сохранится.</p><button class="primary" id="confirm-reset">Да, сбросить демоданные</button><button id="cancel-reset">Отмена</button>`);$('#cancel-reset').onclick=()=>$('#dialog').close();$('#confirm-reset').onclick=()=>{reset();$('#dialog').close();renderModule('control');toast('Демосессия очищена.')}}}
export function renderModule(path){const root=path.split('/')[0];$('#app').dataset.module=root;if(root==='automotive'){$('#app').innerHTML=auto(path.includes('experience'));bindAuto()}else if(root==='commerce'){$('#app').innerHTML=commerce();drawProducts();drawCart();document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;renderModule('commerce')});$('#search').oninput=e=>{query=e.target.value;drawProducts()};$('#sort').onchange=e=>{sort=e.target.value;drawProducts()}}else if(root==='studio'){$('#app').innerHTML=studio();bindStudio()}else if(root==='control'){$('#app').innerHTML=control();bindControl()}else $('#app').innerHTML='<h1>Пространство не найдено</h1><a href="#/">Вернуться на остров</a>';}
